using BuildingManagement.Domain;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

#pragma warning disable CA1725 // Compact mappings use a conventional short builder name.

namespace BuildingManagement.Infrastructure;

internal static class FinancialConfiguration
{
    internal const string Schema = "bms";
    internal static void Record<T>(EntityTypeBuilder<T> b, string table) where T : FinancialRecord
    { b.ToTable(table, Schema); b.HasKey(x => x.Id); b.Property(x => x.Id).UseIdentityColumn(); b.Property(x => x.CreatedAtUtc).HasPrecision(0); b.Property(x => x.UpdatedAtUtc).HasPrecision(0); b.Property(x => x.RowVersion).IsRowVersion(); b.HasIndex(x => x.IsActive); }
    internal static void Money<T>(EntityTypeBuilder<T> b, params string[] properties) where T : class { foreach (var p in properties) b.Property(p).HasPrecision(18, 2); }
}

public sealed class FinancialAccountConfiguration : IEntityTypeConfiguration<FinancialAccount> { public void Configure(EntityTypeBuilder<FinancialAccount> b) { FinancialConfiguration.Record(b, "FinancialAccounts"); b.Property(x => x.AccountKindKey).HasColumnType("varchar(30)").IsRequired(); FinancialConfiguration.Money(b, "CurrentBalance", "AvailableCredit"); b.Property(x => x.AvailableCredit).HasDefaultValue(0); b.ToTable("FinancialAccounts", "bms", t => { t.HasCheckConstraint("CK_FinancialAccounts_OneOwner", "(CASE WHEN [UnitId] IS NULL THEN 0 ELSE 1 END + CASE WHEN [BuildingId] IS NULL THEN 0 ELSE 1 END + CASE WHEN [ComplexId] IS NULL THEN 0 ELSE 1 END) = 1"); t.HasCheckConstraint("CK_FinancialAccounts_KindOwner", "([UnitId] IS NOT NULL AND [AccountKindKey] = 'unit_account') OR ([UnitId] IS NULL AND [AccountKindKey] IN ('current_fund','reserve_fund'))"); t.HasCheckConstraint("CK_FinancialAccounts_AvailableCredit", "[AvailableCredit] >= 0 AND ([UnitId] IS NOT NULL OR [AvailableCredit] = 0)"); }); b.HasIndex(x => new { x.UnitId, x.AccountKindKey }).IsUnique().HasFilter("[UnitId] IS NOT NULL"); b.HasIndex(x => new { x.BuildingId, x.AccountKindKey }).IsUnique().HasFilter("[BuildingId] IS NOT NULL"); b.HasIndex(x => new { x.ComplexId, x.AccountKindKey }).IsUnique().HasFilter("[ComplexId] IS NOT NULL"); b.HasOne<Unit>().WithMany().HasForeignKey(x => x.UnitId).OnDelete(DeleteBehavior.Restrict); b.HasOne<Building>().WithMany().HasForeignKey(x => x.BuildingId).OnDelete(DeleteBehavior.Restrict); b.HasOne<Complex>().WithMany().HasForeignKey(x => x.ComplexId).OnDelete(DeleteBehavior.Restrict); } }
public sealed class FinancialTransactionConfiguration : IEntityTypeConfiguration<FinancialTransaction> { public void Configure(EntityTypeBuilder<FinancialTransaction> b) { b.ToTable("FinancialTransactions", "bms", t => { t.HasCheckConstraint("CK_FinancialTransactions_OneSource", "(CASE WHEN [DemandId] IS NULL THEN 0 ELSE 1 END + CASE WHEN [PaymentId] IS NULL THEN 0 ELSE 1 END + CASE WHEN [ExpenseDisbursementId] IS NULL THEN 0 ELSE 1 END + CASE WHEN [AccountAdjustmentId] IS NULL THEN 0 ELSE 1 END) = 1"); t.HasCheckConstraint("CK_FinancialTransactions_TypeSource", "([TransactionTypeKey] = 'demand' AND [DemandId] IS NOT NULL) OR ([TransactionTypeKey] = 'payment' AND [PaymentId] IS NOT NULL) OR ([TransactionTypeKey] = 'expense_disbursement' AND [ExpenseDisbursementId] IS NOT NULL) OR ([TransactionTypeKey] = 'account_adjustment' AND [AccountAdjustmentId] IS NOT NULL)"); }); b.HasKey(x => x.Id); b.Property(x => x.Id).UseIdentityColumn(); b.Property(x => x.TransactionTypeKey).HasColumnType("varchar(40)"); b.Property(x => x.Description).HasMaxLength(500); b.Property(x => x.OccurredAtUtc).HasPrecision(0); b.Property(x => x.CreatedAtUtc).HasPrecision(0); b.HasIndex(x => x.DemandId).IsUnique().HasFilter("[DemandId] IS NOT NULL"); b.HasIndex(x => x.PaymentId).IsUnique().HasFilter("[PaymentId] IS NOT NULL"); b.HasIndex(x => x.ExpenseDisbursementId).IsUnique().HasFilter("[ExpenseDisbursementId] IS NOT NULL"); b.HasIndex(x => x.AccountAdjustmentId).IsUnique().HasFilter("[AccountAdjustmentId] IS NOT NULL"); } }
public sealed class FinancialTransactionEntryConfiguration : IEntityTypeConfiguration<FinancialTransactionEntry> { public void Configure(EntityTypeBuilder<FinancialTransactionEntry> b) { b.ToTable("FinancialTransactionEntries", "bms", t => { t.HasCheckConstraint("CK_FinancialTransactionEntries_Amount", "[Amount] > 0"); t.HasCheckConstraint("CK_FinancialTransactionEntries_Effect", "[EffectKey] IN ('increase','decrease')"); }); b.HasKey(x => x.Id); b.Property(x => x.Id).UseIdentityColumn(); b.Property(x => x.EffectKey).HasColumnType("varchar(10)"); FinancialConfiguration.Money(b, "Amount", "BalanceAfter"); b.Property(x => x.CreatedAtUtc).HasPrecision(0); b.HasIndex(x => new { x.FinancialAccountId, x.CreatedAtUtc }); b.HasIndex(x => x.FinancialTransactionId); b.HasOne<FinancialTransaction>().WithMany().HasForeignKey(x => x.FinancialTransactionId).OnDelete(DeleteBehavior.Restrict); b.HasOne<FinancialAccount>().WithMany().HasForeignKey(x => x.FinancialAccountId).OnDelete(DeleteBehavior.Restrict); } }

public sealed class ExpenseTypeConfiguration : IEntityTypeConfiguration<ExpenseType> { public void Configure(EntityTypeBuilder<ExpenseType> b) { b.ToTable("ExpenseTypes", "bms", t => { t.HasCheckConstraint("CK_ExpenseTypes_Scope", "[BuildingId] IS NULL OR [ComplexId] IS NULL"); t.HasCheckConstraint("CK_ExpenseTypes_GlobalKey", "[BuildingId] IS NOT NULL OR [ComplexId] IS NOT NULL OR [Key] IS NOT NULL"); }); b.HasKey(x => x.Id); b.Property(x => x.Id).UseIdentityColumn(); b.Property(x => x.Key).HasColumnType("varchar(50)"); b.Property(x => x.Title).HasMaxLength(100); b.Property(x => x.CreatedAtUtc).HasPrecision(0); b.Property(x => x.UpdatedAtUtc).HasPrecision(0); b.Property(x => x.RowVersion).IsRowVersion(); b.HasIndex(x => x.Key).IsUnique().HasFilter("[Key] IS NOT NULL"); b.HasIndex(x => new { x.BuildingId, x.Title }).IsUnique().HasFilter("[BuildingId] IS NOT NULL"); b.HasIndex(x => new { x.ComplexId, x.Title }).IsUnique().HasFilter("[ComplexId] IS NOT NULL"); b.HasOne<Building>().WithMany().HasForeignKey(x => x.BuildingId).OnDelete(DeleteBehavior.Restrict); b.HasOne<Complex>().WithMany().HasForeignKey(x => x.ComplexId).OnDelete(DeleteBehavior.Restrict); } }
public sealed class ExpenseConfiguration : IEntityTypeConfiguration<Expense> { public void Configure(EntityTypeBuilder<Expense> b) { ConfigurationHelpers.Entity(b, "Expenses"); b.ToTable("Expenses", "bms", t => { t.HasCheckConstraint("CK_Expenses_OneScope", "(CASE WHEN [BuildingId] IS NULL THEN 0 ELSE 1 END + CASE WHEN [ComplexId] IS NULL THEN 0 ELSE 1 END) = 1"); t.HasCheckConstraint("CK_Expenses_Amount", "[Amount] > 0"); }); b.Property(x => x.Title).HasMaxLength(200); b.Property(x => x.Description).HasMaxLength(1000); b.Property(x => x.Status).HasColumnType("varchar(20)"); b.Property(x => x.Amount).HasPrecision(18, 2); b.Property(x => x.ExpenseDate).HasPrecision(0); b.Property(x => x.DueDate).HasPrecision(0); b.Property(x => x.FinalizedAtUtc).HasPrecision(0); b.Property(x => x.CancelledAtUtc).HasPrecision(0); b.HasIndex(x => new { x.BuildingId, x.Status, x.ExpenseDate }); b.HasIndex(x => new { x.ComplexId, x.Status, x.ExpenseDate }); b.HasIndex(x => x.ExpenseTypeId); b.HasOne<Building>().WithMany().HasForeignKey(x => x.BuildingId).OnDelete(DeleteBehavior.Restrict); b.HasOne<Complex>().WithMany().HasForeignKey(x => x.ComplexId).OnDelete(DeleteBehavior.Restrict); b.HasOne<ExpenseType>().WithMany().HasForeignKey(x => x.ExpenseTypeId).OnDelete(DeleteBehavior.Restrict); b.HasOne<Party>().WithMany().HasForeignKey(x => x.VendorPartyId).OnDelete(DeleteBehavior.Restrict); } }
public sealed class ExpenseDisbursementConfiguration : IEntityTypeConfiguration<ExpenseDisbursement> { public void Configure(EntityTypeBuilder<ExpenseDisbursement> b) { ConfigurationHelpers.Entity(b, "ExpenseDisbursements"); b.ToTable("ExpenseDisbursements", "bms", t => t.HasCheckConstraint("CK_ExpenseDisbursements_Amount", "[Amount] > 0")); b.Property(x => x.Amount).HasPrecision(18, 2); b.Property(x => x.PaymentMethodKey).HasColumnType("varchar(50)"); b.Property(x => x.Status).HasColumnType("varchar(20)"); b.Property(x => x.PaidAtUtc).HasPrecision(0); b.Property(x => x.Notes).HasMaxLength(500); b.HasIndex(x => new { x.ExpenseId, x.Status }); b.HasIndex(x => new { x.FundAccountId, x.Status }); b.HasOne<Expense>().WithMany().HasForeignKey(x => x.ExpenseId).OnDelete(DeleteBehavior.Restrict); b.HasOne<FinancialAccount>().WithMany().HasForeignKey(x => x.FundAccountId).OnDelete(DeleteBehavior.Restrict); b.HasOne<Party>().WithMany().HasForeignKey(x => x.PayeePartyId).OnDelete(DeleteBehavior.Restrict); } }

