public sealed class DemandAllocationRuleConfiguration : IEntityTypeConfiguration<DemandAllocationRule> { public void Configure(EntityTypeBuilder<DemandAllocationRule> b) { b.ToTable("DemandAllocationRules", "bms", t => t.HasCheckConstraint("CK_DemandAllocationRules_Amounts", "([TotalAmount] IS NULL OR [TotalAmount] > 0) AND ([RateAmount] IS NULL OR [RateAmount] > 0)")); b.HasKey(x => x.Id); b.Property(x => x.Id).UseIdentityColumn(); b.Property(x => x.AllocationMethodKey).HasColumnType("varchar(30)"); b.Property(x => x.AmountModeKey).HasColumnType("varchar(30)"); b.Property(x => x.ResponsiblePartyTypeKey).HasColumnType("varchar(30)"); b.Property(x => x.RedistributionPolicyKey).HasColumnType("varchar(30)"); FinancialConfiguration.Money(b, "TotalAmount", "RateAmount"); b.Property(x => x.Notes).HasMaxLength(500); b.HasIndex(x => x.DemandId).IsUnique(); b.HasOne<Demand>().WithOne().HasForeignKey<DemandAllocationRule>(x => x.DemandId).OnDelete(DeleteBehavior.Restrict); } }
