public sealed class UnitReceivableConfiguration : IEntityTypeConfiguration<UnitReceivable> { public void Configure(EntityTypeBuilder<UnitReceivable> b) { ConfigurationHelpers.Entity(b, "UnitReceivables"); b.ToTable("UnitReceivables", "bms", t => { t.HasCheckConstraint("CK_UnitReceivables_Origin", "(CASE WHEN [DemandAllocationId] IS NULL THEN 0 ELSE 1 END + CASE WHEN [AccountAdjustmentId] IS NULL THEN 0 ELSE 1 END) = 1"); t.HasCheckConstraint("CK_UnitReceivables_Amounts", "[OriginalAmount] > 0 AND [OutstandingAmount] >= 0 AND [OutstandingAmount] <= [OriginalAmount]"); }); FinancialConfiguration.Money(b, "OriginalAmount", "OutstandingAmount"); b.Property(x => x.ResponsiblePartyTypeKey).HasColumnType("varchar(30)"); b.Property(x => x.Status).HasColumnType("varchar(20)"); b.Property(x => x.DueDate).HasPrecision(0); b.HasIndex(x => new { x.UnitAccountId, x.Status, x.DueDate }); b.HasIndex(x => x.FundAccountId); b.HasIndex(x => x.DemandAllocationId).IsUnique().HasFilter("[DemandAllocationId] IS NOT NULL"); b.HasIndex(x => x.AccountAdjustmentId).IsUnique().HasFilter("[AccountAdjustmentId] IS NOT NULL"); b.HasOne<FinancialAccount>().WithMany().HasForeignKey(x => x.UnitAccountId).OnDelete(DeleteBehavior.Restrict); b.HasOne<FinancialAccount>().WithMany().HasForeignKey(x => x.FundAccountId).OnDelete(DeleteBehavior.Restrict); b.HasOne<DemandAllocation>().WithMany().HasForeignKey(x => x.DemandAllocationId).OnDelete(DeleteBehavior.Restrict); b.HasOne<AccountAdjustment>().WithMany().HasForeignKey(x => x.AccountAdjustmentId).OnDelete(DeleteBehavior.Restrict); b.HasOne<Party>().WithMany().HasForeignKey(x => x.ResponsiblePartyId).OnDelete(DeleteBehavior.Restrict); } }
public sealed class PaymentConfiguration : IEntityTypeConfiguration<Payment> { public void Configure(EntityTypeBuilder<Payment> b) { ConfigurationHelpers.Entity(b, "Payments"); b.ToTable("Payments", "bms", t => t.HasCheckConstraint("CK_Payments_Amount", "[Amount] > 0")); b.Property(x => x.Amount).HasPrecision(18, 2); b.Property(x => x.Status).HasColumnType("varchar(30)"); b.Property(x => x.GatewayReference).HasMaxLength(100); b.Property(x => x.BankTrackingCode).HasMaxLength(100); b.Property(x => x.Notes).HasMaxLength(500); b.Property(x => x.PaidAtUtc).HasPrecision(0); b.Property(x => x.SubmittedAtUtc).HasPrecision(0); b.Property(x => x.ConfirmedAtUtc).HasPrecision(0); b.Property(x => x.RejectedAtUtc).HasPrecision(0); b.HasIndex(x => x.GatewayReference).IsUnique().HasFilter("[GatewayReference] IS NOT NULL"); b.HasIndex(x => new { x.UnitAccountId, x.Status }); b.HasIndex(x => new { x.ReceivingFundAccountId, x.Status }); b.HasIndex(x => x.PayerPartyId); b.HasIndex(x => x.PaymentMethodId); b.HasOne<FinancialAccount>().WithMany().HasForeignKey(x => x.UnitAccountId).OnDelete(DeleteBehavior.Restrict); b.HasOne<FinancialAccount>().WithMany().HasForeignKey(x => x.ReceivingFundAccountId).OnDelete(DeleteBehavior.Restrict); b.HasOne<Party>().WithMany().HasForeignKey(x => x.PayerPartyId).OnDelete(DeleteBehavior.Restrict); b.HasOne<PaymentMethod>().WithMany().HasForeignKey(x => x.PaymentMethodId).OnDelete(DeleteBehavior.Restrict); } }
